(async()=>{const w=ms=>new Promise(r=>setTimeout(r,ms));const m=document.getElementById('main');const out=[];
const setv=(el,v)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}))};
const D={lpD_d1:'۳۰۰۰ واژه تا امتحانِ B1',lpD_d2:'۹۰ روز تا امتحان',lpD_d3:'۴۰ دقیقه مترو در روز (بیشتر هم می‌شه شب)',lpD_d4:'اندازهٔ خودم: هر مرور ۸ ثانیه، فراموشی ۱۵٪، هر کارتِ تازه ۳۵ ثانیه'};
for(const k in D){const e=document.getElementById(k);if(e){setv(e,D[k]);out.push('set '+k);}else out.push('NO '+k);await w(200);}
const labs=[...m.querySelectorAll('label')];
const byLab=(re)=>{const L=labs.find(l=>re.test(l.textContent));return L?(L.querySelector('input,textarea,select')||L.nextElementSibling):null};
const sel=[...m.querySelectorAll('select')].filter(s=>/اثرِ محسوس دارد/.test(s.textContent));sel.forEach(s=>{s.selectedIndex=1;s.dispatchEvent(new Event('change',{bubbles:true}))});out.push('effects '+sel.length);
const allT=[...m.querySelectorAll('input[type=text],textarea')];
const near=(re)=>{const h=[...m.querySelectorAll('*')].find(x=>x.children.length<2&&re.test(x.textContent)&&x.textContent.length<120);if(!h)return null;let n=h;for(let i=0;i<6&&n;i++){n=n.nextElementSibling||n.parentElement.nextElementSibling;if(n&&/INPUT|TEXTAREA/.test(n.tagName))return n;const q=n&&n.querySelector&&n.querySelector('input[type=text],textarea');if(q)return q;}return null};
const u=near(/^۳\) مجهول/);if(u){setv(u,'چند دقیقه در روز لازم است و آیا در وقتی که دارم جا می‌شود');out.push('unk '+u.id);}else out.push('NO unk');
const c=near(/^۵\) شرط چیست/);if(c){setv(c,'ده روزِ آخر فقط مرور؛ هر کارت حدودِ ۵ بار مرور و کارت‌های فراموش‌شده هم حساب شوند');out.push('cond '+c.id);}else out.push('NO cond');
const suf=[...m.querySelectorAll('select')].find(s=>/کافی است/.test(s.textContent));if(suf){suf.selectedIndex=1;suf.dispatchEvent(new Event('change',{bubbles:true}));out.push('suff');}
await w(400);const b=[...m.querySelectorAll('button')].find(b=>b.offsetParent&&/^ثبتِ فهم/.test(b.textContent.trim()));if(b){b.scrollIntoView({block:'center'});b.click();out.push('click ثبتِ فهم');}
await w(1500);const id=APP.liveAll().map(r=>r.p.id).pop();return JSON.stringify({out,phase:APP.livePhase(id),bad:window.__bad?__bad():'',head:m.innerText.slice(m.innerText.indexOf('🔭 مسئلهٔ حل‌نشدهٔ خودم'),m.innerText.indexOf('🔭 مسئلهٔ حل‌نشدهٔ خودم')+600)})})()
